definition.script:
def ref = env.PR_BRANCH ?: ''
if (!ref.startsWith('provision/')) { echo "branche '${ref}' hors provision/* — rien a appliquer"; return }
def rest = ref.substring('provision/'.length())
def envName = rest.substring(rest.lastIndexOf('-') + 1)
def appName = rest.substring(0, rest.lastIndexOf('-'))
def manifest = "clients/provisioned/applications/${appName}.ansible.yml"
currentBuild.displayName = "apply ${appName}/${envName} (PR #${env.PR_NUMBER})"
echo "Demande FUSIONNEE — application=${appName} env=${envName} manifeste=${manifest}"

// ── DEMANDE EN ATTENTE : validation humaine + identite Vault ──────────────
def creds = input(
  id: 'apply', message: "Appliquer l'application ${appName} en ${envName} ? Fournissez VOTRE identite Vault (voie A).",
  parameters: [
    string(name: 'VAULT_USER', defaultValue: '', description: 'Login annuaire (ex. oscar)'),
    password(name: 'VAULT_USER_PASSWORD', defaultValue: '', description: 'Mot de passe annuaire')
  ])

// ── APPLY NOMINATIF : delegue au job prouve selfservice-app-deploy ────────
build job: 'selfservice-app-deploy', wait: true, parameters: [
  string(name: 'MANIFEST', value: manifest),
  string(name: 'ENVIRONMENT', value: envName),
  string(name: 'ADMIN_VIA', value: 'proxy-oauth2'),
  string(name: 'VAULT_USER', value: creds.VAULT_USER),
  [$class: 'PasswordParameterValue', name: 'VAULT_USER_PASSWORD', value: creds.VAULT_USER_PASSWORD]
]
echo "Apply nominatif lance pour ${appName}/${envName} par ${creds.VAULT_USER}"
